/* eslint-disable react-hooks/exhaustive-deps */

import React, { useRef, useEffect, useState, memo } from 'react';
import { useGLTF } from "@react-three/drei";
import { Canvas } from "@react-three/fiber";
import * as THREE from "three";

// ============================================
// 🎭 FIXED LIP SYNC - NORMAL SPEED
// ============================================

const LipSyncManager = ({ scene, isSpeaking, currentText }) => {
  useEffect(() => {
    if (!scene || !isSpeaking) return;

    const meshes = [];
    scene.traverse((child) => {
      if (child.isMesh && child.morphTargetInfluences && child.morphTargetDictionary) {
        meshes.push(child);
      }
    });

    if (meshes.length === 0) return;

    const applyViseme = (intensity = 0.6) => {
      meshes.forEach(mesh => {
        const dict = mesh.morphTargetDictionary;
        
        // Reset all
        Object.keys(dict).forEach(key => {
          if (key.includes('viseme') || key.includes('mouth')) {
            mesh.morphTargetInfluences[dict[key]] = 0;
          }
        });

        // Apply random mouth movement with moderate intensity
        const visemeKeys = Object.keys(dict).filter(k => k.includes('viseme') || k.includes('mouth'));
        if (visemeKeys.length > 0) {
          const randomKey = visemeKeys[Math.floor(Math.random() * visemeKeys.length)];
          mesh.morphTargetInfluences[dict[randomKey]] = intensity * (0.4 + Math.random() * 0.4);
        }
      });
    };

    // ✅ FIXED: Changed from 100ms to 180ms for natural lip movement
    const lipSyncInterval = setInterval(() => {
      applyViseme();
    }, 180); // SLOWER = NATURAL LIP SYNC

    return () => {
      clearInterval(lipSyncInterval);
      meshes.forEach(mesh => {
        if (mesh.morphTargetInfluences) {
          for (let i = 0; i < mesh.morphTargetInfluences.length; i++) {
            mesh.morphTargetInfluences[i] = 0;
          }
        }
      });
    };
  }, [isSpeaking, currentText, scene]);

  return null;
};

// ============================================
// 🎭 FEMALE AVATAR (Priya)
// ============================================

const FemaleAvatar = memo(({ avatarMode, isAISpeaking, currentText, onIntroComplete }) => {
  const group = useRef();
  const mixerRef = useRef();
  const actionsRef = useRef({});
  const currentActionRef = useRef(null);
  const talkingIndexRef = useRef(0);
  const idleIndexRef = useRef(0);
  const hasCalledIntroRef = useRef(false);
  const isIdleCycleActiveRef = useRef(true);

  const { scene } = useGLTF("/avatars/priya.glb");
  const walkGltf = useGLTF("/animations/female/F_Walk_002.glb");
  const danceGltf = useGLTF("/animations/female/F_Dances_001.glb");
  const crouchGltf = useGLTF("/animations/female/F_Crouch_Walk_001.glb");
  const idleVar1Gltf = useGLTF("/animations/female/F_Standing_Idle_Variations_001.glb");
  const idleVar2Gltf = useGLTF("/animations/female/F_Standing_Idle_Variations_002.glb");
  const idleVar3Gltf = useGLTF("/animations/female/F_Standing_Idle_Variations_003.glb");
  const idleVar4Gltf = useGLTF("/animations/female/F_Standing_Idle_Variations_004.glb");
  const idleVar5Gltf = useGLTF("/animations/female/F_Standing_Idle_Variations_005.glb");
  const idleVar6Gltf = useGLTF("/animations/female/F_Standing_Idle_Variations_006.glb");
  const idleVar7Gltf = useGLTF("/animations/female/F_Standing_Idle_Variations_007.glb");
  const idleVar8Gltf = useGLTF("/animations/female/F_Standing_Idle_Variations_008.glb");
  const idleVar9Gltf = useGLTF("/animations/female/F_Standing_Idle_Variations_009.glb");
  const talk1Gltf = useGLTF("/animations/female/F_Talking_Variations_001.glb");
  const talk2Gltf = useGLTF("/animations/female/F_Talking_Variations_002.glb");
  const talk3Gltf = useGLTF("/animations/female/F_Talking_Variations_003.glb");
  const talk4Gltf = useGLTF("/animations/female/F_Talking_Variations_004.glb");
  const talk5Gltf = useGLTF("/animations/female/F_Talking_Variations_005.glb");
  const talk6Gltf = useGLTF("/animations/female/F_Talking_Variations_006.glb");

  useEffect(() => {
    if (!scene) return;
    mixerRef.current = new THREE.AnimationMixer(scene);

    const animationsData = {
      idleVar1: { clips: idleVar1Gltf.animations, speed: 0.6 },
      idleVar2: { clips: idleVar2Gltf.animations, speed: 0.6 },
      idleVar3: { clips: idleVar3Gltf.animations, speed: 0.6 },
      idleVar4: { clips: idleVar4Gltf.animations, speed: 0.6 },
      idleVar5: { clips: idleVar5Gltf.animations, speed: 0.6 },
      idleVar6: { clips: idleVar6Gltf.animations, speed: 0.6 },
      idleVar7: { clips: idleVar7Gltf.animations, speed: 0.6 },
      idleVar8: { clips: idleVar8Gltf.animations, speed: 0.6 },
      idleVar9: { clips: idleVar9Gltf.animations, speed: 0.6 },
      talk1: { clips: talk1Gltf.animations, speed: 0.7 },
      talk2: { clips: talk2Gltf.animations, speed: 0.7 },
      talk3: { clips: talk3Gltf.animations, speed: 0.7 },
      talk4: { clips: talk4Gltf.animations, speed: 0.7 },
      talk5: { clips: talk5Gltf.animations, speed: 0.7 },
      talk6: { clips: talk6Gltf.animations, speed: 0.7 },
      walk: { clips: walkGltf.animations, speed: 0.7 },
      dance: { clips: danceGltf.animations, speed: 0.6 },
      crouch: { clips: crouchGltf.animations, speed: 0.6 },
    };

    Object.entries(animationsData).forEach(([name, config]) => {
      if (config.clips?.length > 0) {
        const action = mixerRef.current.clipAction(config.clips[0]);
        action.setLoop(THREE.LoopRepeat);
        action.timeScale = config.speed;
        actionsRef.current[name] = action;
      }
    });

    if (!hasCalledIntroRef.current) {
      hasCalledIntroRef.current = true;
      setTimeout(() => {
        playIdleCycle();
        if (onIntroComplete) {
          onIntroComplete({
            message: "Hi! I'm Priya, your Biology tutor. I'm so excited to explore the fascinating world of life sciences with you today!",
            companionId: 'priya_biology',
          });
        }
      }, 800);
    }

    return () => mixerRef.current?.stopAllAction();
  }, [scene]);

  const playIdleCycle = () => {
    if (!isIdleCycleActiveRef.current) return;
    const idleVariations = ['idleVar1', 'idleVar2', 'idleVar3', 'idleVar4', 'idleVar5', 'idleVar6', 'idleVar7', 'idleVar8', 'idleVar9'];
    const variation = idleVariations[idleIndexRef.current % idleVariations.length];
    playAnimation(variation, () => {
      idleIndexRef.current++;
      playIdleCycle();
    });
  };

  const playTalkingCycle = () => {
    if (avatarMode !== "talk") {
      isIdleCycleActiveRef.current = true;
      playIdleCycle();
      return;
    }

    const talkingAnimations = ['talk1', 'talk2', 'talk3', 'talk4', 'talk5', 'talk6'];
    const currentTalk = talkingAnimations[talkingIndexRef.current % talkingAnimations.length];
    playAnimation(currentTalk, () => {
      talkingIndexRef.current++;
      if (avatarMode === "talk") playTalkingCycle();
      else {
        isIdleCycleActiveRef.current = true;
        playIdleCycle();
      }
    });
  };

  const playAnimation = (name, onFinish) => {
    const action = actionsRef.current[name];
    if (!action) {
      onFinish?.();
      return;
    }

    if (currentActionRef.current && currentActionRef.current !== action) {
      currentActionRef.current.fadeOut(0.2);
    }

    action.reset().fadeIn(0.2).play();
    currentActionRef.current = action;

    if (onFinish) {
      const handler = (e) => {
        if (e.action === action) {
          mixerRef.current.removeEventListener("finished", handler);
          onFinish();
        }
      };
      mixerRef.current.addEventListener("finished", handler);
    }
  };

  useEffect(() => {
    if (!actionsRef.current.idleVar1) return;

    if (avatarMode === 'walk' || avatarMode === 'dance' || avatarMode === 'crouch' || avatarMode === 'sit') {
      isIdleCycleActiveRef.current = false;
      const animMap = { sit: 'crouch' };
      const animName = animMap[avatarMode] || avatarMode;
      if (actionsRef.current[animName]) {
        const action = actionsRef.current[animName];
        if (currentActionRef.current) currentActionRef.current.fadeOut(0.2);
        action.reset().fadeIn(0.2).play();
        currentActionRef.current = action;
      }
      return;
    }

    if (avatarMode === "talk") {
      isIdleCycleActiveRef.current = false;
      talkingIndexRef.current = 0;
      playTalkingCycle();
    } else {
      isIdleCycleActiveRef.current = true;
      playIdleCycle();
    }
  }, [avatarMode]);

  useEffect(() => {
    const clock = new THREE.Clock();
    let frameId;
    const animate = () => {
      frameId = requestAnimationFrame(animate);
      mixerRef.current?.update(clock.getDelta());
    };
    frameId = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(frameId);
  }, []);

  return (
    <>
      <primitive ref={group} object={scene} scale={2} position={[0, -1.5, 0]} />
      <LipSyncManager scene={scene} isSpeaking={isAISpeaking} currentText={currentText} />
    </>
  );
});

// ============================================
// 🎭 MALE AVATAR (Omkar)
// ============================================

const MaleAvatar = memo(({ avatarMode, isAISpeaking, currentText, onIntroComplete }) => {
  const group = useRef();
  const mixerRef = useRef();
  const actionsRef = useRef({});
  const currentActionRef = useRef(null);
  const talkingIndexRef = useRef(0);
  const idleIndexRef = useRef(0);
  const hasCalledIntroRef = useRef(false);
  const isIdleCycleActiveRef = useRef(true);

  const { scene } = useGLTF("/avatars/omkar.glb");
  const walkGltf = useGLTF("/animations/male/M_Walk_001.glb");
  const danceGltf = useGLTF("/animations/male/M_Dances_001.glb");
  const crouchGltf = useGLTF("/animations/male/M_Crouch_Walk_001.glb");
  const idleVar1Gltf = useGLTF("/animations/male/M_Standing_Idle_Variations_001.glb");
  const idleVar2Gltf = useGLTF("/animations/male/M_Standing_Idle_Variations_002.glb");
  const idleVar3Gltf = useGLTF("/animations/male/M_Standing_Idle_Variations_003.glb");
  const idleVar4Gltf = useGLTF("/animations/male/M_Standing_Idle_Variations_004.glb");
  const idleVar5Gltf = useGLTF("/animations/male/M_Standing_Idle_Variations_005.glb");
  const idleVar6Gltf = useGLTF("/animations/male/M_Standing_Idle_Variations_006.glb");
  const idleVar7Gltf = useGLTF("/animations/male/M_Standing_Idle_Variations_007.glb");
  const idleVar8Gltf = useGLTF("/animations/male/M_Standing_Idle_Variations_008.glb");
  const idleVar9Gltf = useGLTF("/animations/male/M_Standing_Idle_Variations_009.glb");
  const talk1Gltf = useGLTF("/animations/male/M_Talking_Variations_001.glb");
  const talk2Gltf = useGLTF("/animations/male/M_Talking_Variations_002.glb");
  const talk3Gltf = useGLTF("/animations/male/M_Talking_Variations_003.glb");
  const talk4Gltf = useGLTF("/animations/male/M_Talking_Variations_004.glb");
  const talk5Gltf = useGLTF("/animations/male/M_Talking_Variations_005.glb");
  const talk6Gltf = useGLTF("/animations/male/M_Talking_Variations_006.glb");

  useEffect(() => {
    if (!scene) return;
    mixerRef.current = new THREE.AnimationMixer(scene);

    const animationsData = {
      idleVar1: { clips: idleVar1Gltf.animations, speed: 0.6 },
      idleVar2: { clips: idleVar2Gltf.animations, speed: 0.6 },
      idleVar3: { clips: idleVar3Gltf.animations, speed: 0.6 },
      idleVar4: { clips: idleVar4Gltf.animations, speed: 0.6 },
      idleVar5: { clips: idleVar5Gltf.animations, speed: 0.6 },
      idleVar6: { clips: idleVar6Gltf.animations, speed: 0.6 },
      idleVar7: { clips: idleVar7Gltf.animations, speed: 0.6 },
      idleVar8: { clips: idleVar8Gltf.animations, speed: 0.6 },
      idleVar9: { clips: idleVar9Gltf.animations, speed: 0.6 },
      talk1: { clips: talk1Gltf.animations, speed: 0.7 },
      talk2: { clips: talk2Gltf.animations, speed: 0.7 },
      talk3: { clips: talk3Gltf.animations, speed: 0.7 },
      talk4: { clips: talk4Gltf.animations, speed: 0.7 },
      talk5: { clips: talk5Gltf.animations, speed: 0.7 },
      talk6: { clips: talk6Gltf.animations, speed: 0.7 },
      walk: { clips: walkGltf.animations, speed: 0.7 },
      dance: { clips: danceGltf.animations, speed: 0.6 },
      crouch: { clips: crouchGltf.animations, speed: 0.6 },
    };

    Object.entries(animationsData).forEach(([name, config]) => {
      if (config.clips?.length > 0) {
        const action = mixerRef.current.clipAction(config.clips[0]);
        action.setLoop(THREE.LoopRepeat);
        action.timeScale = config.speed;
        actionsRef.current[name] = action;
      }
    });

    if (!hasCalledIntroRef.current) {
      hasCalledIntroRef.current = true;
      setTimeout(() => {
        playIdleCycle();
        if (onIntroComplete) {
          onIntroComplete({
            message: "Hello! I'm Omkar, your AI tutor. Ready to learn together? Let's make today's session amazing!",
            companionId: 'omkar_ai',
          });
        }
      }, 800);
    }

    return () => mixerRef.current?.stopAllAction();
  }, [scene]);

  const playIdleCycle = () => {
    if (!isIdleCycleActiveRef.current) return;
    const idleVariations = ['idleVar1', 'idleVar2', 'idleVar3', 'idleVar4', 'idleVar5', 'idleVar6', 'idleVar7', 'idleVar8', 'idleVar9'];
    const variation = idleVariations[idleIndexRef.current % idleVariations.length];
    playAnimation(variation, () => {
      idleIndexRef.current++;
      playIdleCycle();
    });
  };

  const playTalkingCycle = () => {
    if (avatarMode !== "talk") {
      isIdleCycleActiveRef.current = true;
      playIdleCycle();
      return;
    }

    const talkingAnimations = ['talk1', 'talk2', 'talk3', 'talk4', 'talk5', 'talk6'];
    const currentTalk = talkingAnimations[talkingIndexRef.current % talkingAnimations.length];
    playAnimation(currentTalk, () => {
      talkingIndexRef.current++;
      if (avatarMode === "talk") playTalkingCycle();
      else {
        isIdleCycleActiveRef.current = true;
        playIdleCycle();
      }
    });
  };

  const playAnimation = (name, onFinish) => {
    const action = actionsRef.current[name];
    if (!action) {
      onFinish?.();
      return;
    }

    if (currentActionRef.current && currentActionRef.current !== action) {
      currentActionRef.current.fadeOut(0.2);
    }

    action.reset().fadeIn(0.2).play();
    currentActionRef.current = action;

    if (onFinish) {
      const handler = (e) => {
        if (e.action === action) {
          mixerRef.current.removeEventListener("finished", handler);
          onFinish();
        }
      };
      mixerRef.current.addEventListener("finished", handler);
    }
  };

  useEffect(() => {
    if (!actionsRef.current.idleVar1) return;

    if (avatarMode === 'walk' || avatarMode === 'dance' || avatarMode === 'crouch' || avatarMode === 'sit') {
      isIdleCycleActiveRef.current = false;
      const animMap = { sit: 'crouch' };
      const animName = animMap[avatarMode] || avatarMode;
      if (actionsRef.current[animName]) {
        const action = actionsRef.current[animName];
        if (currentActionRef.current) currentActionRef.current.fadeOut(0.2);
        action.reset().fadeIn(0.2).play();
        currentActionRef.current = action;
      }
      return;
    }

    if (avatarMode === "talk") {
      isIdleCycleActiveRef.current = false;
      talkingIndexRef.current = 0;
      playTalkingCycle();
    } else {
      isIdleCycleActiveRef.current = true;
      playIdleCycle();
    }
  }, [avatarMode]);

  useEffect(() => {
    const clock = new THREE.Clock();
    let frameId;
    const animate = () => {
      frameId = requestAnimationFrame(animate);
      mixerRef.current?.update(clock.getDelta());
    };
    frameId = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(frameId);
  }, []);

  return (
    <>
      <primitive ref={group} object={scene} scale={2} position={[0, -1.5, 0]} />
      <LipSyncManager scene={scene} isSpeaking={isAISpeaking} currentText={currentText} />
    </>
  );
});

// ============================================
// 🎭 MAIN AVATAR3D COMPONENT
// ============================================

export const Avatar3D = ({ 
  isLoading, 
  companion, 
  customAnimation, 
  isAISpeaking, 
  currentSpeakingText 
}) => {
  const [loadError, setLoadError] = useState(null);
  const [introComplete, setIntroComplete] = useState(false);
  const onIntroCompleteRef = useRef(null);

  const isFemale = companion?.id === 'priya_biology';
  const avatarMode = customAnimation || (isAISpeaking ? "talk" : "idle");

  useEffect(() => {
    const handleError = (error) => {
      console.error('❌ Avatar loading error:', error);
      setLoadError(`Failed to load ${isFemale ? 'Priya' : 'Omkar'} avatar`);
    };
    window.addEventListener('error', handleError);
    return () => window.removeEventListener('error', handleError);
  }, [isFemale]);

  const handleIntroComplete = (data) => {
    if (!introComplete) {
      setIntroComplete(true);
      if (onIntroCompleteRef.current) {
        onIntroCompleteRef.current(data);
      }
    }
  };

  return (
    <div className="relative w-full h-full bg-gradient-to-b from-slate-900 via-purple-900/20 to-slate-900 rounded-lg overflow-hidden">
      {isLoading && (
        <div className="absolute inset-0 flex items-center justify-center bg-black/50 z-50">
          <div className="flex flex-col items-center space-y-4">
            <div className="w-16 h-16 border-4 border-purple-500 border-t-transparent rounded-full animate-spin"></div>
            <p className="text-white font-medium">Loading {isFemale ? "Priya" : "Omkar"}...</p>
          </div>
        </div>
      )}

      {loadError && (
        <div className="absolute inset-0 flex items-center justify-center bg-red-900/30 z-50">
          <p className="text-red-300 font-medium">{loadError}</p>
        </div>
      )}

      <Canvas
        shadows
        camera={{ position: [0, 0, 3], fov: 45 }}
        style={{ width: '100%', height: '100%' }}
      >
        <ambientLight intensity={0.8} />
        <spotLight position={[10, 10, 10]} angle={0.3} penumbra={1} intensity={1.2} castShadow />
        <pointLight position={[-10, -10, -10]} intensity={0.5} />
        <directionalLight position={[5, 5, 5]} intensity={0.7} />

        <React.Suspense fallback={null}>
          {isFemale ? (
            <FemaleAvatar 
              avatarMode={avatarMode} 
              isAISpeaking={isAISpeaking} 
              currentText={currentSpeakingText}
              onIntroComplete={handleIntroComplete}
            />
          ) : (
            <MaleAvatar 
              avatarMode={avatarMode} 
              isAISpeaking={isAISpeaking} 
              currentText={currentSpeakingText}
              onIntroComplete={handleIntroComplete}
            />
          )}
        </React.Suspense>
      </Canvas>

      {isAISpeaking && (
        <div className="absolute bottom-8 left-1/2 transform -translate-x-1/2 bg-purple-600/90 backdrop-blur-sm px-6 py-3 rounded-full shadow-2xl animate-pulse">
          <div className="flex items-center space-x-3">
            <div className="flex space-x-1">
              <div className="w-2 h-4 bg-white rounded-full animate-bounce" style={{ animationDelay: '0ms' }}></div>
              <div className="w-2 h-4 bg-white rounded-full animate-bounce" style={{ animationDelay: '150ms' }}></div>
              <div className="w-2 h-4 bg-white rounded-full animate-bounce" style={{ animationDelay: '300ms' }}></div>
            </div>
            <span className="text-white font-medium text-sm">Speaking...</span>
          </div>
        </div>
      )}
    </div>
  );
};

export default Avatar3D;
